extra_css:
/* titles: sizes of the book, relative to the text */
.lia-slide__content h1.h1 { font-size: 130%; }
.lia-slide__content h2.h1 { font-size: 130%; }
.lia-slide__content h3.h1 { font-size: 115%; }
.lia-slide__content h4.h1 { font-size: 100%; }
/* quotes: smaller, indented, no panel */
.lia-slide__content .lia-quote { background: transparent; border: none; box-shadow: none; margin-left: 3em; padding: 0; font-size: 85%; }
.lia-slide__content .lia-quote, .lia-slide__content .lia-quote__text, .lia-slide__content .lia-quote p { color: rgba(var(--color-text), 0.8); font-style: normal; font-weight: normal; text-align: left; }
.lia-slide__content .lia-quote footer, .lia-slide__content .lia-quote cite, .lia-slide__content .lia-quote .lia-cite { text-align: left; }
.lia-slide__content .lia-quote cite, .lia-slide__content .lia-quote .lia-cite { font-style: italic; }
/* code: thin teal rules as on the website */
.lia-slide__content .lia-code:not(.lia-code--inline) { border: none; border-top: 1px solid #44aabb; border-bottom: 1px solid #44aabb; border-radius: 0; }
.lia-slide__content .lia-code--inline { background: transparent; color: inherit; padding: 0 2px; border: none; }
.lia-slide__content .ejs-frame iframe { border: 1px dotted #44aabb !important; border-radius: 0 !important; }
/* links: no underline until hovered */
.lia-slide__content a { text-decoration: none; }
.lia-slide__content a:hover { text-decoration: underline; }
/* figures: centered */
.lia-slide__content .lia-figure { margin-left: auto; margin-right: auto; }
.lia-slide__content .lia-figure__media, .lia-slide__content p > img { max-width: 100%; }
